using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "Forgotten Letter OmenData", menuName = "Data/Battle/Omens System/Omen Data/Moonie/ForgottenLetterOmenData")]
public class ForgottenLetterOmenData : OnPlayerCorruptEnemyOmenData
{
	[Header("Forgotten Letter")]
	[SerializeField]
	private ConvertAction convertAction;

	public override void ActivateOmen(GameObject target = null)
	{
		bool flag = false;
		UnitsDiceActivation component = target.GetComponent<UnitsDiceActivation>();
		if (component.BasicDiceSpawned)
		{
			DiceInstance basicDiceInstance = component.BasicDiceInstance;
			if (convertAction.CheckCondition(basicDiceInstance))
			{
				convertAction.DiceSelected(basicDiceInstance);
				flag = true;
			}
		}
		if (component.BoostDiceSpawned && component.IsBoosted)
		{
			DiceInstance boostDiceInstance = component.BoostDiceInstance;
			if (convertAction.CheckCondition(boostDiceInstance))
			{
				convertAction.DiceSelected(boostDiceInstance);
				flag = true;
			}
		}
		if (flag)
		{
			convertAction.ConvertKickOmen();
		}
	}
}
